  function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
  function makeContent(title, pack) {
    var out = '<article class="lecture-text lecture-expanded">';
    out += '<h2>' + esc(title) + '</h2>';
    out += '<p><strong>Цель занятия.</strong> Сформировать целостное представление о теме, научиться выбирать обоснованную последовательность действий и контролировать качество результата с соблюдением требований охраны труда.</p>';
    pack.forEach(function (item, i) {
      out += '<h3>' + (i + 1) + '. ' + esc(item[0]) + '</h3><p>' + esc(item[1]) + '</p>';
    });
    out += '<h3>Порядок выполнения учебного задания</h3><ol>';
    out += '<li>Изучить исходные данные: чертёж, технологическую карту, инструкцию и требования безопасности.</li>';
    out += '<li>Определить базовые параметры, оборудование, инструмент и средства контроля.</li>';
    out += '<li>Составить последовательность действий и указать контрольные точки.</li>';
    out += '<li>Выполнить расчёт или проверку на учебном примере, зафиксировать результат.</li>';
    out += '<li>Сравнить результат с требованиями документации, объяснить возможные отклонения и предложить корректирующие действия.</li></ol>';
    out += '<h3>Самопроверка</h3><ol>';
    out += '<li>Какова основная цель рассматриваемого процесса и какие исходные данные необходимы?</li>';
    out += '<li>Какие параметры необходимо контролировать и какими средствами?</li>';
    out += '<li>Назовите не менее трёх типичных ошибок и объясните, как их предупредить.</li>';
    out += '<li>Какие действия необходимо прекратить при выявлении опасного состояния или несоответствия?</li></ol>';
    out += '<h3>Практическое задание</h3><p>Подготовьте краткую технологическую карту по теме: укажите цель, исходные данные, оборудование и инструмент, последовательность из 5–8 шагов, контрольные параметры, требования безопасности и критерии приёмки. Для каждого этапа поясните, почему он необходим.</p>';
    out += '<h3>Вывод</h3><p>Качественное выполнение работы требует соблюдения установленной последовательности, применения подходящих средств контроля и документирования результата. При отклонении сначала устанавливают причину, затем выполняют разрешённое корректирующее действие и повторно подтверждают качество.</p>';
    out += '</article>';
    return out;
  }
  var db = window.MDK_DATA && window.MDK_DATA["04.01"];
  if (!db || !Array.isArray(db.sections)) return;
  db.sections.forEach(function (section) {
    (section.topics || []).forEach(function (topic) {
      var updated = false;
      (topic.lectures || []).forEach(function (lecture, i) {
        var pack = MATERIAL[lecture.title] || MATERIAL[topic.title];
        if (!pack) return;
        lecture.content = makeContent(lecture.title || topic.title, pack);
        lecture.duration = 60;
        lecture.learningOutcomes = ['объясняет основные понятия и принципы темы', 'выбирает последовательность выполнения работы', 'применяет требования безопасности и контроля качества'];
        updated = true;
      });
      if (!updated) return;
      topic.duration = 60;
      topic.learningObjectives = ['систематизировать теоретические знания по теме', 'сформировать практический алгоритм действий', 'научиться оценивать результат по документации'];
      topic.methodicalVersion = 'expanded-v3';
    });
  });
